(function(){
const extra=[
['Sabah ve akşam','Sabah ve akşam duası','اَللّٰهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ','Allah’ım! Senin lütfunla sabaha ulaştık, senin lütfunla akşama eriştik. Sen dileyince dirilir, yine sen dileyince ölürüz. Huzuruna varılacak olan da sensin.','Ebû Dâvûd, Edeb, 110; Tirmizî, De’avât, 13'],
['Sabah ve akşam','Korunma duası','بِسْمِ اللّٰهِ الَّذٖي لَا يَضُرُّ مَعَ اسْمِهٖ شَيْءٌ فِي الْأَرْضِ وَلَا في السَّمٰاءِ وَهُوَ السَّمٖيعُ الْعَلٖيمُ','İsminin anılmasıyla ne yerde ne de gökte hiçbir şeyin zarar veremeyeceği Allah’ın adıyla. O, hakkıyla işiten, kemaliyle bilendir.','Tirmizî, De’avât, 13; Ebû Dâvûd, Edeb, 110'],
['Uyku','Uyanınca okunan dua','الْحَمْدُ لِلَّهِ الَّذِى أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ','Bizi öldürdükten sonra dirilten Allah’a hamdolsun. Yeniden diriliş ve dönüş O’nadır.','Buhârî, Tevhîd, 13'],
['Günlük hayat','Elbise giyerken','اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ أَسْأَلُكَ خَيْرَهُ وَخَيْرَ مَا صُنِعَ لَهُ وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ','Allah’ım! Hamd sanadır. Bunu bana sen giydirdin. Onun ve yapılış gayesinin hayrını senden diler, şerrinden sana sığınırım.','Tirmizî, Libâs, 29'],
['Günlük hayat','Evden çıkarken','اَللّٰهُمَّ إِنّٖي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ أَوْ أَزِلَّ أَوْ أُزَلَّ أَوْ أَظْلِمَ أَوْ أُظْلَمَ أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ','Allah’ım! Sapmaktan ve saptırılmaktan, ayağımın kaymasından ve kaydırılmaktan, zulmetmekten ve zulme uğramaktan, cahillik etmekten ve cahilce davranışa uğramaktan sana sığınırım.','Ebû Dâvûd, Edeb, 11'],
['Yeme içme','Yemekten sonra','الْحَمْدُ لِلَّهِ الَّذِى أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِينَ','Bizi yediren, içiren ve Müslümanlardan kılan Allah’a hamdolsun.','Ebû Dâvûd, Et’ıme, 52'],
['Yolculuk','Yolculuk duası','اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى وَمِنَ الْعَمَلِ مَا تَرْضَى','Allah’ım! Bu yolculuğumuzda senden iyilik, takva ve razı olacağın amelleri dileriz. Yolculuğumuzu kolaylaştır, uzağını yakın eyle; seferde yardımcımız, geride bıraktıklarımızın koruyucusu sensin.','Müslim, Hac, 425'],
['Yolculuk','Yolculuğun sıkıntısından korunma','اللَّهُمَّ إِنِّى أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمُنْقَلَبِ وَدَعْوَةِ الْمَظْلُومِ','Allah’ım! Yolculuğun yorgunluk ve sıkıntılarından, kötü bir dönüşten, mazlumun bedduasından, mal ve ailede kötü bir manzara görmekten sana sığınırım.','Müslim, Hac, 426'],
['Uyku','Yatarken teslimiyet duası','اَللّٰهُمَّ أَسْلَمْتُ نَفْسٖي إِلَيْكَ وَوَجَّهْتُ وَجْهٖي إِلَيْكَ وَفَوَّضْتُ أَمْرٖي إِلَيْكَ','Allah’ım! Kendimi sana teslim ettim, yüzümü sana çevirdim, işimi sana havale ettim. Rızanı umarak ve azabından korkarak sana sığındım. Senden başka sığınak yoktur. İndirdiğin kitaba ve gönderdiğin peygambere iman ettim.','Buhârî, De’avât, 6, 7, 9; Müslim, Zikir ve Dua, 56-57'],
['Sıkıntı ve afiyet','Keder ve acizlikten korunma','اللَّهُمَّ إِنِّى أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ','Allah’ım! Kederden, üzüntüden, acizlikten, tembellikten, cimrilikten, korkaklıktan, borç yükünden ve insanların baskısından sana sığınırım.','Buhârî, De’avât, 38'],
['Uyku','Gece korunma duası','اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَجْمَعُ عِبَادَكَ','Allah’ım! Kullarını bir araya getireceğin gün beni azabından koru.','Tirmizî, De’avât, 18']
];
extra.forEach(x=>bigDuas.unshift({kind:'Sünnette dua',category:x[0],title:x[1],arabic:x[2],text:x[3],source:x[4]}));

const feature=[...document.querySelectorAll('.feature-card')].find(x=>x.dataset.pageTarget==='duas');
if(feature){feature.querySelector('strong').textContent='Dua ve Hadisler';feature.querySelector('small').textContent='Dualar, hadisler ve Esmâü’l-Hüsnâ';}

const brand=document.querySelector('.brand-button');brand?.removeAttribute('data-page-target');if(brand){brand.setAttribute('aria-label','Menüyü aç');brand.querySelector('.brand-mark').textContent='☰';}
const drawer=document.createElement('aside');drawer.className='app-drawer';drawer.innerHTML='<div class="drawer-head"><strong>İslam Rehberi</strong><button class="drawer-close" aria-label="Menüyü kapat">×</button></div><nav class="drawer-nav"><button data-go="home">⌂ Ana Sayfa</button><button data-go="quran">☾ Kur’an Oku</button><button data-go="qibla">⌖ Kıble</button><button data-go="duas">♡ Dua ve Hadisler</button></nav><section class="widget-settings"><span class="eyebrow">SAATLİK AYET WIDGET’I</span><h3>Widget görünümü</h3><label><input id="widget-arabic" type="checkbox" checked> Arapça metni göster</label><label><input id="widget-tafsir" type="checkbox"> Tefsir bağlantısını göster</label><small>Android ana ekranında widget ekleme bölümünden “Saatlik Ayet”i seçin.</small></section>';
const shade=document.createElement('div');shade.className='drawer-shade';document.body.append(shade,drawer);
const notification=document.querySelector('.notification-settings');if(notification){notification.classList.add('drawer-notification');drawer.append(notification);}
const close=()=>document.body.classList.remove('drawer-open');brand?.addEventListener('click',()=>document.body.classList.add('drawer-open'));shade.onclick=close;drawer.querySelector('.drawer-close').onclick=close;drawer.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{showPage(b.dataset.go);close()});

function widgetPrefs(){const a=document.getElementById('widget-arabic'),t=document.getElementById('widget-tafsir');localStorage.setItem('widgetArabic',a.checked?'1':'0');localStorage.setItem('widgetTafsir',t.checked?'1':'0');nativeIslam()?.setWidgetPreferences({showArabic:a.checked,showTafsir:t.checked}).catch(()=>{});}
const wa=document.getElementById('widget-arabic'),wt=document.getElementById('widget-tafsir');wa.checked=localStorage.getItem('widgetArabic')!=='0';wt.checked=localStorage.getItem('widgetTafsir')==='1';wa.onchange=wt.onchange=widgetPrefs;

const hourly=document.createElement('section');hourly.className='hourly-verse';hourly.innerHTML='<div><span class="eyebrow">HER SAAT YENİ BİR AYET</span><strong id="hourly-ref">Kur’an hazırlanıyor</strong></div><p id="hourly-arabic" class="hourly-arabic"></p><p id="hourly-tr"></p><button id="hourly-open">Kur’an’da aç</button>';
document.querySelector('.home-hero')?.before(hourly);
function hourlyVerse(){if(!state.corpus?.surahs?.length)return;const hour=Math.floor(Date.now()/3600000),global=(Number((BigInt(hour)*2654435761n)%6236n)+1);let found,surah;for(const s of state.corpus.surahs){found=s.ayahs.find(a=>a.global===global);if(found){surah=s;break}}if(!found)return;document.getElementById('hourly-ref').textContent=`${surah.name} Suresi, ${found.number}. ayet`;document.getElementById('hourly-arabic').textContent=found.ar;document.getElementById('hourly-arabic').hidden=!wa.checked;document.getElementById('hourly-tr').textContent=found.tr;document.getElementById('hourly-open').onclick=()=>{state.selected=surah.number;showPage('quran');renderSurah(surah.number);};}
setInterval(hourlyVerse,60000);setTimeout(hourlyVerse,700);wa.addEventListener('change',hourlyVerse);

const reciters={
 'ar.alafasy':128,'ar.abdulbasit':192,'ar.husary':128,'ar.minshawi':128
};
const sel=document.getElementById('arabic-reciter');if(sel){const bad=sel.querySelector('[value="ar.abdulbasitmurattal"]');if(bad)bad.value='ar.abdulbasit';}
function playSequence(edition,bitrate,label){const s=selectedSurah();if(!s)return;let i=0;const p=$('quran-audio');p.hidden=false;const next=()=>{if(i>=s.ayahs.length){setStatus(`${s.name} suresi ${label} tamamlandı.`);return;}const a=s.ayahs[i++];p.src=`https://cdn.islamic.network/quran/audio/${bitrate}/${edition}/${a.global}.mp3`;p.load();p.play().catch(()=>setStatus('Ses başlatılamadı. Bağlantıyı denetleyin.'));};p.onended=next;p.onerror=()=>setTimeout(next,250);next();setStatus(`${s.name} suresi ${label} kesintisiz oynatılıyor.`);}
$('play-arabic').onclick=()=>{const e=sel?.value||'ar.alafasy';playSequence(e,reciters[e]||128,'Arapça')};
$('download-arabic').replaceWith(Object.assign(document.createElement('button'),{id:'download-arabic',className:'soft-button',textContent:'↓ Arapça indir'}));
$('download-arabic').onclick=async()=>{const s=selectedSurah(),e=sel?.value||'ar.alafasy';if(!s)return;const b=$('download-arabic');b.disabled=true;try{const c=await caches.open(`arabic-audio-${e}`);for(let i=0;i<s.ayahs.length;i++){const u=`https://cdn.islamic.network/quran/audio/${reciters[e]||128}/${e}/${s.ayahs[i].global}.mp3`;if(!await c.match(u))await c.add(u);b.textContent=`İndiriliyor ${i+1}/${s.ayahs.length}`;}setStatus(`${s.name} suresinin seçili kârî sesleri çevrimdışı kullanım için kaydedildi.`);}catch(_){setStatus('Sesler indirilemedi. İnternet bağlantısını denetleyin.');}finally{b.disabled=false;b.textContent='↓ Arapça indir';}};

const oldRender=renderDuas;renderDuas=function(){oldRender();if(guideKind!=='dua')return;const list=$('dua-list'),tools=list.querySelector('.hadith-tools'),select=tools?.querySelector('select');if(!select)return;select.hidden=false;tools.classList.remove('single');select.innerHTML='<option value="">Bütün dua kategorileri</option>';[...new Set(bigDuas.map(x=>x.category||x.kind))].sort((a,b)=>a.localeCompare(b,'tr')).forEach(x=>select.add(new Option(x,x)));const input=tools.querySelector('input'),cards=list.querySelector('.library-cards');const paint=()=>{const term=normalize(input.value),cat=select.value;cards.replaceChildren();bigDuas.filter(x=>(!cat||(x.category||x.kind)===cat)&&(!term||normalize(`${x.title} ${x.text||''} ${x.source}`).includes(term))).forEach(x=>{let text=x.text;if(x.surah)text=state.corpus?.surahs[x.surah-1]?.ayahs[x.ayah-1]?.tr||x.title;const c=document.createElement('article');c.className='dua-card';c.innerHTML=`<span class="dua-reference">${x.category||x.kind} · ${x.source}</span><h2>${x.title}</h2>${x.arabic?`<p class="dua-arabic">${x.arabic}</p>`:''}<p class="dua-translation">${text}</p>`;cards.append(c)});};input.oninput=paint;select.onchange=paint;paint();};
})();
